// Generates crates/sirene-core/src/math/macros_data.rs from KaTeX's predefined macros
// (spec/latex-math.md, LMATH-12). Development tool: the generated file is checked in.
//
// Setup (once): the KaTeX checkout described in scripts/katex-fixtures.mjs, at tag v0.19.1.
// Run:
//   node --no-warnings scripts/katex-macros.mjs
//
// KaTeX's `src/macros.ts` defines commands in terms of others, mostly as strings of TeX
// (`\dots` is not one, since it looks ahead; such macros are functions). Node 24 reads the
// TypeScript directly, with the resolver hook of scripts/katex-ts-loader.mjs for KaTeX's
// extensionless imports, so this script reads the real table. The Rust file holds the string
// macros in two byte-sorted slices (control sequences and single characters), and lists the
// function macros, which the expander implements by hand. Adapted from KaTeX, MIT licensed,
// Copyright (c) 2013-2020 Khan Academy and other contributors; see THIRD-PARTY-NOTICES.

import { register } from "node:module";
import { writeFileSync } from "node:fs";

register("./katex-ts-loader.mjs", import.meta.url);
const { default: macros } = await import(new URL("../local/katex/src/macros.ts", import.meta.url));

function rustString(s) {
  let out = '"';
  for (const ch of s) {
    const cp = ch.codePointAt(0);
    if (ch === '"' || ch === "\\") out += "\\" + ch;
    else if (cp >= 0x20 && cp < 0x7f) out += ch;
    else out += `\\u{${cp.toString(16)}}`;
  }
  return out + '"';
}

function byBytes(a, b) {
  return Buffer.compare(Buffer.from(a[0]), Buffer.from(b[0]));
}

const controls = [];
const chars = [];
const functions = [];
for (const [name, definition] of Object.entries(macros)) {
  if (typeof definition === "function") {
    functions.push(name);
  } else if (typeof definition === "string") {
    if (name.startsWith("\\")) controls.push([name.slice(1), definition]);
    else chars.push([name, definition]);
  } else {
    throw new Error(`unexpected macro ${name}: ${typeof definition}`);
  }
}
controls.sort(byBytes);
chars.sort(byBytes);
functions.sort();

const rows = (entries) =>
  entries.map(([k, v]) => `    (${rustString(k)}, ${rustString(v)}),`).join("\n");

const out = `// GENERATED by scripts/katex-macros.mjs from KaTeX's src/macros.ts (v0.19.1). Do not edit:
// change the script and run it again. Adapted from KaTeX, MIT licensed, Copyright (c) 2013-2020
// Khan Academy and other contributors; see THIRD-PARTY-NOTICES.
//
// The macros that are a string of TeX, keyed without the backslash and sorted by the bytes of
// the key. A test checks the order.

/// Control sequences, such as \`\\bra\` (key \`bra\`).
pub(super) static CONTROLS: &[(&str, &str)] = &[
${rows(controls)}
];

/// Single characters that expand, such as \`~\`.
pub(super) static CHARS: &[(&str, &str)] = &[
${rows(chars)}
];

/// The macros KaTeX defines with a function, because they look ahead or read arguments. The
/// expander implements the ones it supports (see \`expander.rs\`); a test checks the list.
pub(super) static FUNCTIONS: &[&str] = &[
${functions.map((f) => `    ${rustString(f.startsWith("\\") ? f.slice(1) : f)},`).join("\n")}
];
`;

writeFileSync(new URL("../crates/sirene-core/src/math/macros_data.rs", import.meta.url), out);
console.log(
  `${controls.length} control sequence macros, ${chars.length} character macros, ` +
    `${functions.length} function macros`,
);
